#include <iostream>
#include <string>

class StringReplacer {
public:
    // Overloaded replace functions based on const correctness
    std::string& replace(std::string& str, size_t pos, size_t n, const std::string& newStr) {
        str.replace(pos, n, newStr);
        return str;
    }
    const std::string& replace(const std::string& str, size_t pos, size_t n, const std::string& newStr) {
        // For demonstration, just return the input string as is
        return str;
    }
};

int main() {
    StringReplacer replacer;
    std::string myStr = "Hello, World!";
    // Call non-const version to modify the string
    replacer.replace(myStr, 7, 5, "C++");
    std::cout << myStr << std::endl; // Outputs: Hello, C++!
    // Call const version with const string
    const std::string constStr = "Const String";
    replacer.replace(constStr, 0, 5, "New"); // Uses const version
    return 0;
}
